/* Game build profiles: addresses and structure offsets inside the supported executables.
 * Found by analysing the decrypted in-memory images (tools/re); the tables are generated by
 * tools/re/gen_profiles.py into profiles.inc. The profile is chosen by exe name and image size,
 * then every anchor signature of the profile is verified before any game memory is touched;
 * a mismatch disables all game features.
 *
 * Drakensang (2008): UI::Server::Open enables the render path pass compose_with_gui; camera
 * Graphics::Server::GetCamera 0x411aa3; Actions::LoadLocation -> LocationManager::ChangeLocation;
 * Entity::IsVisibleByLod 0x6259bf; fog through nVariableServer FogDistances; models through
 * Util::SegmentedGfxUtil::CreateAndSetupGraphicsEntities.
 * The River of Time: PostEffectsServer::SetComposeMode(mode) switches compose / compose_gui /
 * compose_dof / compose_gui_dof; fog is set per frame by a function writing shader params 37/38
 * (FogDistances/FogColor) from two fog layers; otherwise the same Mangalore classes. */
#pragma once
#include "core.h"

int game_check(DWORD addr, const char *hexbytes);  /* 1 if code at addr matches "aa bb cc" */
int game_readable(const void *p, DWORD size);
void **game_iat_slot(const char *dll, const char *func);
void game_data_file(WCHAR *path, const WCHAR *base);   /* <game>\<base>_<exe>.txt, else <base>.txt */

/* hook.c: inline detours (prologue bytes given as hex define the relocated length) */
typedef struct Detour {
    BYTE *target;
    int   len;
    BYTE  orig[16];
    BYTE *tramp;
    int   active;
} Detour;
int  detour_install(Detour *d, DWORD target, const char *prologue, void *fn, void **orig);
void detour_remove(Detour *d);
void detour_remove_all(void);

/* defer.c: run game actions outside the render frame (from the message pump) */
void defer_init(void);
void defer_shutdown(void);
int  defer_call(void (*fn)(const char *a, const char *b), const char *a, const char *b);
int  defer_stats(char *out, int outsz);

enum { UI_PASSES_D1 = 1, UI_COMPOSEMODE = 2 };   /* how the GUI is composed into the frame */
enum { FOG_VARSERVER = 1, FOG_SHADERFUNC = 2 };   /* how fog distances reach the shaders */
enum { PE_NONE = 0, PE_D1 = 1 };                  /* layout of the post effects parameter block */

typedef struct GameSig { DWORD addr; const char *bytes; } GameSig;

typedef struct GameAddrs {
    const char *name;
    const WCHAR *exe;
    DWORD image_size;

    /* Nebula2 basics: nString::Set(const char*) on a zeroed 0x34-byte buffer, dtor; nArray; Release */
    DWORD nstring_set, nstring_dtor;
    int   narray_num, narray_elems;
    DWORD release;

    /* graphics server -> level -> camera; level root cell bounding box */
    DWORD gfxserver_ptr;
    int   gfxserver_level, level_camera, level_rootcell, cell_bbox;

    /* camera entity */
    DWORD cam_settransform; const char *pro_cam_settransform;
    int   cam_transform, cam_ncamera, cam_viewproj_dirty, ncam_aov, ncam_proj_dirty;

    /* UI composition */
    int   ui_mode;
    DWORD sceneserver_ptr; int scene_renderpath, rp_sections, section_stride, section_name, section_passes;
    DWORD posteffects_ptr, set_compose_mode; const char *pro_set_compose_mode; int pe_section, pe_mode;
    int   pass_stride, pass_name, pass_enabled;

    /* level travel */
    DWORD locationmgr_ptr, change_location; int locmgr_pending_len;

    /* graphics frame state */
    DWORD ngfxserver_ptr; int gfx_in_begin_frame;

    /* draw distance and visibility zones */
    DWORD entity_lodvisible, light_lodvisible; const char *pro_entity_lodvisible, *pro_light_lodvisible;
    int   lod_maxdist, lod_minsize;
    DWORD vis[2]; const char *pro_vis[2];

    /* fog */
    int   fog_mode;
    DWORD varserver_ptr, var_setvector, var_gethandle; const char *pro_var_setvector;
    DWORD fog_func; const char *pro_fog_func; int fog_near[2], fog_far[2];

    /* spawning models */
    DWORD seggfx_create, level_removeentity, narray_ptr_dtor; int entity_cell;

    /* model LOD nodes (nLodNode::RenderTransform) and camera clip planes in nCamera2 */
    DWORD lodnode_render; const char *pro_lodnode_render; int lodnode_thresholds, lodnode_maxdist;
    int   ncam_near, ncam_far;

    /* post effects server: parameter block applied to shaders, global light and sky every frame */
    int   pe_layout; DWORD pe_server_ptr, pe_apply; const char *pro_pe_apply; int pe_params;

    /* SpeedTree types: LOD limits passed when a tree type is loaded */
    DWORD tree_load; const char *pro_tree_load;

    /* hiding static objects while a level loads, adding SpeedTrees to the level's forest */
    const char *pro_seggfx_create; DWORD env_seggfx_ret;
    DWORD forest_mgr_ptr, forest_add_tree;

    /* walking a level's cells: child cells (nFixedArray), entity pools (nArray per type), entity resource name */
    int   cell_children, cell_pool, cell_ntypes, entity_resname;

    /* LevelLoader::Load: brackets the synchronous level load */
    DWORD level_load; const char *pro_level_load;

    /* moving the player party (FormationManager) */
    DWORD formation_mgr_ptr, formation_place, formation_finish;

    GameSig sigs[96];   /* all must match */
} GameAddrs;

extern const GameAddrs *G;   /* current profile; NULL if the exe is not supported */
int game_ok(void);           /* profile selected and all signatures verified */
int game_is_d1(void);        /* game_ok() and it is Drakensang (2008) */

