#define NSTRING_SIZE             0x34

static inline const char *nstring_get(const BYTE *s)
{
    const char *p = *(const char *const *)s;
    return p ? p : (const char *)(s + 4);
}

/* Build a game nString from a C string in a zeroed buffer of at least NSTRING_SIZE bytes. */
typedef void (__fastcall *PFN_NStringSet)(void *self, void *edx, const char *s);
typedef void (__fastcall *PFN_NStringDtor)(void *self, void *edx);
static inline void nstring_make(BYTE *buf, const char *s)
{
    memset(buf, 0, NSTRING_SIZE);
    ((PFN_NStringSet)ADDR_NSTRING_SET)(buf, NULL, s);
}
static inline void nstring_free(BYTE *buf)
{
    ((PFN_NStringDtor)ADDR_NSTRING_DTOR)(buf, NULL);
}
